<?php

namespace Database\Seeders;

use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;

class BeninAdministrativeSeeder extends Seeder
{
    public function run()
    {
        // 1. Création des départements
        $departements = [
            'ALIBORI', 'ATACORA', 'ATLANTIQUE', 'BORGOU', 'COLLINES', 
            'COUFFO', 'DONGA', 'LITTORAL', 'MONO', 'OUEME', 'PLATEAU', 'ZOU'
        ];

        foreach ($departements as $dep) {
            $depCode = $this->sanitizeCode($dep);
            $depId = DB::table('departements')->insertGetId([
                'code' => $depCode,
                'libelle' => $dep,
            ]);

            // 2. Création des communes pour chaque département
            $communes = $this->getCommunesByDepartement($dep);
            
            foreach ($communes as $commune) {
                $communeCode = $this->sanitizeCode($commune);
                $communeId = DB::table('communes')->insertGetId([
                    'code' => $communeCode,
                    'libelle' => $commune,
                    'departement_id' => $depId,
                ]);

                // 3. Création des arrondissements pour chaque commune
                $arrondissements = $this->getArrondissementsByCommune($commune);
                
                foreach ($arrondissements as $arrdt) {
                    $arrdtCode = $this->sanitizeCode($arrdt);
                    $arrdtId = DB::table('arrondissements')->insertGetId([
                        'code' => $arrdtCode,
                        'libelle' => $arrdt,
                        'commune_id' => $communeId,
                    ]);

                    // 4. Création des localités pour chaque arrondissement
                    $localites = $this->getLocalitesByArrondissement($arrdt);
                    
                    foreach ($localites as $loc) {
                        $locCode = $this->sanitizeCode($loc);
                        DB::table('localites')->insert([
                            'code' => $locCode,
                            'libelle' => $loc,
                            'arrondissement_id' => $arrdtId,
                        ]);
                    }
                }
            }
        }
    }

    private function sanitizeCode(string $name): string
    {
        return strtolower(Str::slug($name, ''));
    }

